#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using NUnit.Framework;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

// Read-only checks AFTER explicit InstallImpossibleEntries. Never invokes an
// installer, Start/Action/Select/Step, sport launch, import, save or art fallback.
public sealed class ImpossibleMenuIntegrationTests
{
    const string FrontPath="Assets/TruckSports/Scenes/TruckSports.unity";
    const string InformationPath="Assets/TruckSports/Art/Logos/Catalogue.json";
    const BindingFlags Any=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
    [Serializable] sealed class OriginalAction {public ulong fileId;public string key;}
    [Serializable] sealed class OriginalCard {public ulong fileId;public string name,title,description;public OriginalAction[] actions;}
    [Serializable] sealed class Information {public string scene,title,players;}
    [Serializable] sealed class InformationFile {public Information[] entries;}
    [Serializable] sealed class OriginalBaseline {public string frontSceneSha256,informationSha256;public OriginalCard[] cards;public Information[] information;}
    static OriginalBaseline Baseline=>JsonUtility.FromJson<OriginalBaseline>(BaselineJson);
    static Type Runtime(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static Type EditorType(string name)=>Type.GetType("LWS.TruckSports.Editor."+name+", Assembly-CSharp-Editor",true);
    static object Read(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static object[] Entries=>((IEnumerable)Runtime("SportsImpossibleGames").GetProperty("All").GetValue(null)).Cast<object>().ToArray();
    static Component[] Components(GameObject root,Type type)=>root.GetComponentsInChildren(type,true).Cast<Component>().ToArray();
    static ulong Identity(UnityEngine.Object value)=>GlobalObjectId.GetGlobalObjectIdSlow(value).targetObjectId;
    static string Hash(string path){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
    static Information[] InformationEntries()
    {
        Assert.That(File.Exists(InformationPath),Is.True);var file=JsonUtility.FromJson<InformationFile>(File.ReadAllText(InformationPath));Assert.That(file?.entries,Is.Not.Null);return file.entries;
    }
    sealed class SavedScenes:IDisposable
    {
        readonly SceneSetup[] previous;
        readonly Dictionary<string,string> hashes=new Dictionary<string,string>();
        public SavedScenes()
        {
            Assert.That(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling,Is.False,"Stopped compiled EditMode test required.");
            for(int i=0;i<SceneManager.sceneCount;i++)Assert.That(SceneManager.GetSceneAt(i).isDirty,Is.False,"Preserve existing unsaved scene edits before read-only menu checks.");
            previous=EditorSceneManager.GetSceneManagerSetup();Track(InformationPath);
        }
        void Track(string path){Assert.That(File.Exists(path),Is.True,"Explicit author/integration must create the real saved asset before this test: "+path);if(!hashes.ContainsKey(path))hashes.Add(path,Hash(path));}
        public Scene Open(string path){Track(path);return EditorSceneManager.OpenScene(path,OpenSceneMode.Single);}
        public Component Front()
        {
            var scene=Open(FrontPath);var fronts=scene.GetRootGameObjects().SelectMany(root=>Components(root,Runtime("SportsFrontEnd"))).ToArray();Assert.That(fronts,Has.Length.EqualTo(1));return fronts[0];
        }
        public void Dispose()
        {
            try{foreach(var pair in hashes)Assert.That(Hash(pair.Key),Is.EqualTo(pair.Value),"A read-only check must not rewrite saved scene/catalogue bytes: "+pair.Key);}
            finally{if(previous.Any(item=>item.isLoaded&&item.isActive))EditorSceneManager.RestoreSceneManagerSetup(previous);}
        }
    }
    static GameObject[] Cards(Component front)=>(GameObject[])Read(Read(front,"catalogue"),"cards");
    static string Label(GameObject card,string child)
    {
        var transform=card.transform.Find(child);Assert.That(transform,Is.Not.Null,card.name+"/"+child);var label=transform.GetComponents<Component>().Single(component=>component!=null&&component.GetType().FullName=="TMPro.TextMeshProUGUI");return new SerializedObject(label).FindProperty("m_text").stringValue;
    }
    static Component Image(Transform root,string path)
    {
        var child=root.Find(path);Assert.That(child,Is.Not.Null,root.name+"/"+path);return child.GetComponents<Component>().Single(component=>component!=null&&component.GetType().FullName=="UnityEngine.UI.Image");
    }
    static void ImageUses(Component image,Sprite expected)
    {
        var serialized=new SerializedObject(image);Assert.That(serialized.FindProperty("m_Sprite").objectReferenceValue,Is.SameAs(expected));Assert.That(serialized.FindProperty("m_RaycastTarget").boolValue,Is.False,"Owned artwork must not block the real Heat action.");
    }
    static Sprite Art(string folder,string scene)
    {
        string path="Assets/TruckSports/Art/"+folder+"/"+scene+".png";var sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(sprite,Is.Not.Null,"Original imported sport artwork/current gameplay capture required; never use a template fallback: "+path);Assert.That(AssetDatabase.GetAssetPath(sprite),Is.EqualTo(path));var importer=AssetImporter.GetAtPath(path)as TextureImporter;Assert.That(importer,Is.Not.Null);Assert.That(importer.textureType,Is.EqualTo(TextureImporterType.Sprite));Assert.That(importer.spriteImportMode,Is.EqualTo(SpriteImportMode.Single));Assert.That(importer.mipmapEnabled,Is.False);Assert.That(importer.wrapMode,Is.EqualTo(TextureWrapMode.Clamp));Assert.That(sprite.rect.width,Is.GreaterThan(32));Assert.That(sprite.rect.height,Is.GreaterThan(32));return sprite;
    }
    [Test] public void SavedCollectionAddsOnlyTwentyOneCardsAndPreservesActualBaselineIdentitiesAndCopy()
    {
        using(var scenes=new SavedScenes())
        {
            var front=scenes.Front();var cards=Cards(front);var baseline=Baseline;var entries=Entries;Assert.That(entries,Has.Length.EqualTo(21));Assert.That(cards.Length,Is.EqualTo(baseline.cards.Length+entries.Length),"Build-scene count is not menu-card count; derive the collection from its actual saved pre-integration baseline.");Assert.That(cards.All(card=>card!=null),Is.True);Assert.That(cards.Distinct().Count(),Is.EqualTo(cards.Length));
            for(int i=0;i<baseline.cards.Length;i++)
            {
                var original=baseline.cards[i];var card=cards[i];Assert.That(Identity(card),Is.EqualTo(original.fileId),"Existing card identity/order must survive explicit additive integration: "+original.name);Assert.That(card.name,Is.EqualTo(original.name));Assert.That(Label(card,"Sport"),Is.EqualTo(original.title));Assert.That(Label(card,"Description"),Is.EqualTo(original.description));var actions=Components(card,Runtime("SportsMenuAction"));Assert.That(actions.Length,Is.EqualTo(original.actions.Length));foreach(var old in original.actions){var action=actions.SingleOrDefault(value=>Identity(value)==old.fileId);Assert.That(action,Is.Not.Null,original.name+" original action component identity");Assert.That(Read(action,"action"),Is.EqualTo(old.key));}
            }
            var keys=new HashSet<string>(entries.Select(entry=>(string)Read(entry,"key")));foreach(var card in cards.Skip(baseline.cards.Length)){var actions=Components(card,Runtime("SportsMenuAction"));Assert.That(actions,Has.Length.EqualTo(1));Assert.That(keys.Remove((string)Read(actions[0],"action")),Is.True,"Exactly one appended card per new key; no duplicate or unrelated card.");}Assert.That(keys,Is.Empty);
            TestContext.WriteLine("SAVED_MENU baselineCards="+baseline.cards.Length+" newDefinitions="+entries.Length+" actualCards="+cards.Length+"; original identity/copy retained. This is saved configuration evidence, not Windows navigation/visual acceptance.");
        }
    }
    [Test] public void EveryNewSavedActionBindsItsOwnDistinctLogoIconCurrentPreviewAndTheSharedHero()
    {
        using(var scenes=new SavedScenes())
        {
            var front=scenes.Front();var pages=(GameObject[])Read(front,"pages");var heroes=Components(pages[1],Runtime("SportsCatalogueHero"));Assert.That(heroes,Has.Length.EqualTo(1));var hero=heroes[0];foreach(string field in new[]{"logo","preview","title","description","content"}){var target=Read(hero,field)as Component;Assert.That(target,Is.Not.Null);Assert.That(target.transform.IsChildOf(hero.transform),Is.True,"Hero presentation fields must belong to the actual saved shared showcase.");}
            var information=InformationEntries();var cards=Cards(front);var allActions=Components(front.gameObject,Runtime("SportsMenuAction"));var artHashes=new Dictionary<string,HashSet<string>>();foreach(string kind in new[]{"Logos","Icons/Impossible07","Previews"})artHashes[kind]=new HashSet<string>();
            foreach(var entry in Entries)
            {
                string key=(string)Read(entry,"key"),scene=(string)Read(entry,"scene");var actions=allActions.Where(action=>(string)Read(action,"action")==key).ToArray();Assert.That(actions,Has.Length.EqualTo(1),"One real saved Heat action for "+key);var action=actions[0];Assert.That(Read(action,"button"),Is.Not.Null);Assert.That(((Component)Read(action,"button")).gameObject,Is.EqualTo(action.gameObject));var card=cards.Single(value=>action.transform.IsChildOf(value.transform));Assert.That(Components(card,Runtime("SportsMenuAction")),Has.Length.EqualTo(1));Assert.That(action.transform.IsChildOf(pages[1].transform),Is.True);
                var choices=action.GetComponents(Runtime("SportsCatalogueChoice")).Cast<Component>().ToArray();Assert.That(choices,Has.Length.EqualTo(1));var choice=choices[0];var info=information.Single(item=>item.scene==scene);var logo=Art("Logos",scene);var icon=Art("Icons/Impossible07",scene);var preview=Art("Previews",scene);Assert.That(Read(choice,"hero"),Is.SameAs(hero));Assert.That(Read(choice,"scene"),Is.EqualTo(scene));Assert.That(Read(choice,"title"),Is.EqualTo(info.title));Assert.That(Read(choice,"description"),Is.EqualTo((string)Read(entry,"description")+"\n"+info.players));Assert.That(Read(choice,"logo"),Is.SameAs(logo));Assert.That(Read(choice,"preview"),Is.SameAs(preview));ImageUses(Image(card.transform,"Original sport logo"),logo);ImageUses(Image(card.transform,"Custom sport icon"),icon);ImageUses(Image(card.transform,"Rounded gameplay frame/Sport preview"),preview);
                Assert.That(preview.rect.width,Is.GreaterThanOrEqualTo(320));Assert.That(preview.rect.height,Is.GreaterThanOrEqualTo(180));Assert.That(preview.rect.width/preview.rect.height,Is.InRange(1.25f,2.4f),"A current gameplay preview must not be a square icon/logo substituted for a real supported viewport capture.");string previewHash=Hash(AssetDatabase.GetAssetPath(preview));Assert.That(previewHash,Is.Not.EqualTo(Hash(AssetDatabase.GetAssetPath(logo))));Assert.That(previewHash,Is.Not.EqualTo(Hash(AssetDatabase.GetAssetPath(icon))));foreach(var pair in new[]{new KeyValuePair<string,Sprite>("Logos",logo),new KeyValuePair<string,Sprite>("Icons/Impossible07",icon),new KeyValuePair<string,Sprite>("Previews",preview)})Assert.That(artHashes[pair.Key].Add(Hash(AssetDatabase.GetAssetPath(pair.Value))),Is.True,"Copied placeholder/shared sport artwork must not satisfy distinct original art/current preview bindings: "+scene+"/"+pair.Key);
            }
        }
    }
    [Test] public void SavedPaginationAndCollectionCaptionUseTheActualCardCountAndEightCardPages()
    {
        using(var scenes=new SavedScenes())
        {
            var front=scenes.Front();var catalogue=Read(front,"catalogue");var cards=Cards(front);Assert.That(cards.Length,Is.EqualTo(Baseline.cards.Length+Entries.Length));int pageSize=(int)Read(catalogue,"pageSize");Assert.That(pageSize,Is.EqualTo(8));int expected=Mathf.Max(1,Mathf.CeilToInt(cards.Length/(float)pageSize));Assert.That(Read(catalogue,"Pages"),Is.EqualTo(expected));var indicator=(Component)Read(catalogue,"indicator");Assert.That(new SerializedObject(indicator).FindProperty("m_text").stringValue,Is.EqualTo("SPORTS  1 / "+expected));Assert.That(((GameObject)Read(catalogue,"previous")).activeSelf,Is.False);Assert.That(((GameObject)Read(catalogue,"next")).activeSelf,Is.EqualTo(expected>1));for(int i=0;i<cards.Length;i++)Assert.That(cards[i].activeSelf,Is.EqualTo(i<pageSize),"Explicit installer must save its actual first page; tests never call Step/Refresh to repair it.");var pages=(GameObject[])Read(front,"pages");Assert.That(Label(pages[0],"Collection"),Does.StartWith(cards.Length+" PLAYABLE TRUCK SPORTS. ONE COLLECTION."));
        }
    }
    [Test] public void CataloguePreservesExistingInformationAndDerivesEachNewCapacityFromItsActualSavedAuthority()
    {
        using(var scenes=new SavedScenes())
        {
            var information=InformationEntries();var baseline=Baseline;Assert.That(information.Length,Is.EqualTo(baseline.information.Length+Entries.Length));Assert.That(information.Select(item=>item.scene).Distinct().Count(),Is.EqualTo(information.Length));foreach(var original in baseline.information){var actual=information.SingleOrDefault(item=>item.scene==original.scene);Assert.That(actual,Is.Not.Null);Assert.That(actual.title,Is.EqualTo(original.title),original.scene+" designer title preserved");Assert.That(actual.players,Is.EqualTo(original.players),original.scene+" existing information preserved");}
            foreach(var entry in Entries)
            {
                string name=(string)Read(entry,"scene"),path=(string)Read(entry,"ScenePath");var saved=scenes.Open(path);var authorities=saved.GetRootGameObjects().SelectMany(root=>Components(root,Runtime("SportsEventSession"))).ToArray();Assert.That(authorities,Has.Length.EqualTo(1));var authority=authorities[0];int minimum=(int)Read(authority,"MinimumPlayers"),maximum=(int)Read(authority,"MaximumPlayers");Assert.That(minimum,Is.GreaterThan(0));Assert.That(maximum,Is.GreaterThanOrEqualTo(minimum));string capacity=minimum==maximum?maximum.ToString():minimum+"–"+maximum;var actual=information.Single(item=>item.scene==name);Assert.That(actual.title,Is.EqualTo((string)Read(authority,"Title")));Assert.That(actual.players,Is.EqualTo(capacity+" PARTICIPANTS · UP TO "+Mathf.Min(4,maximum)+" LOCAL HUMANS · AI"),name+" must advertise its real inherited/fixed capacity, including Moon's eight trucks.");
            }
        }
    }
    [Test] public void NewActionKeysResolveToTheirExactSavedSceneAndOneExistingBuildRoute()
    {
        using(var scenes=new SavedScenes())
        {
            var front=scenes.Front();var actions=Components(front.gameObject,Runtime("SportsMenuAction"));var sceneList=(string[])EditorType("SportsBuilder").GetMethod("SceneList").Invoke(null,null);foreach(var entry in Entries)
            {
                string key=(string)Read(entry,"key"),scene=(string)Read(entry,"scene"),path=(string)Read(entry,"ScenePath");Assert.That(actions.Count(action=>(string)Read(action,"action")==key),Is.EqualTo(1));object[] byKey={key,null},byScene={scene,null};Assert.That(Runtime("SportsImpossibleGames").GetMethod("TryFindKey").Invoke(null,byKey),Is.EqualTo(true));Assert.That(Runtime("SportsImpossibleGames").GetMethod("TryFindScene").Invoke(null,byScene),Is.EqualTo(true));Assert.That(byKey[1],Is.SameAs(entry));Assert.That(byScene[1],Is.SameAs(entry));Assert.That(EditorType("SportsMenuArtAuthoring").GetMethod("SceneFor").Invoke(null,new object[]{key}),Is.EqualTo(scene));Assert.That(path,Is.EqualTo("Assets/"+scene+"/Scenes/"+scene+".unity"));var asset=AssetDatabase.LoadAssetAtPath<SceneAsset>(path);Assert.That(asset,Is.Not.Null,"A menu definition is not an authored playable scene.");Assert.That(asset.name,Is.EqualTo(scene));Assert.That(sceneList.Count(value=>value==path),Is.EqualTo(1),"Existing build/navigation mapping must include each exact real scene once; never launch/rebuild it in an EditMode menu check.");
            }
        }
    }
